"""Compounds (समास) of a reading: grouping, type, vigraha and the forward rule chain.

  * grouping: ``mayur.samasa_group`` (the segmenter's member flags, checked);
  * type: ``mayur.samasa_type.decide``, a fixed order of tests each citing its सूत्र, from what
    the sentence shows (member forms, word classes, agreement, gender). The choice among the
    grammatically possible types is a heuristic: ``Compound.basis`` starts with "heuristic:" and
    ``Compound.note`` records the decision and its rule;
  * vigraha: ``mayur.samasa_vigraha``, following the type, with forms generated by vidyut;
  * rule chain: ``mayur.samasa.derive`` (type rule, 1.2.46, 2.4.71, internal sandhi RUN, final
    inflection RUN through vidyut); ``Compound.derivable`` says whether it reproduced the text.
"""

from __future__ import annotations

from dataclasses import replace
from typing import TYPE_CHECKING

from mayur import samasa_group, samasa_type, samasa_vigraha
from mayur.model import Compound, Morph, Reading
from mayur.samasa_type import (AVYAYIBHAVA, BAHUVRIHI, DVANDVA, DVIGU, KARMADHARAYA, NAN_BAHUVRIHI,  # noqa: F401
                               NAN_TATPURUSHA, TATPURUSHA, UNKNOWN, UPAPADA, Decision)

if TYPE_CHECKING:
    from mayur import samasa

_TYPE_CODE = r"2\.[12]\.\d+"


def relation(final_stem: str) -> str:
    """Vibhakti of the first member as decided by the final member (षष्ठी by default)."""
    found = samasa_type._final_relation(final_stem)
    return found[0] if found else "षष्ठी"


def _code(note: str) -> str:
    """The type rule of a decision: the first सूत्र of book 2 its note cites."""
    import re
    m = re.search(_TYPE_CODE, note)
    return m.group(0) if m else ""


def derivation(reading: Reading, comp: Compound, d: Decision) -> "samasa.SamasaDerivation":
    """Forward rule chain (mayur.samasa) for ``comp`` of the decided type ``d``."""
    from mayur import samasa
    words = [reading.words[i] for i in comp.members]
    morphs = [replace(w.morph, stem=samasa_type.stem_of(w)) if w.morph else Morph(form=w.form, lemma=w.form,
                                                                                    kind="stem") for w in words]
    key = d.rule or {UPAPADA: "उपपद", DVIGU: "द्विगु", NAN_TATPURUSHA: "नञ्", NAN_BAHUVRIHI: BAHUVRIHI}.get(
        d.samasa, d.samasa)
    rule_note = d.note.split("; classes:")[0]
    return samasa.derive(morphs, morphs[-1], key, relation=d.relation, surface=comp.stem,
                         forms=[w.form for w in words], rule_code=_code(rule_note), rule_note=rule_note,
                         inner=d.inner)


def _surface_stem(reading: Reading, members: list[int]) -> str:
    """The compound stem as written: member forms re-joined by the sandhi outcome whose
    सूत्र-s the segmenter recorded for each junction (that choice reproduced the text)."""
    from mayur import sandhi
    parts = [reading.words[i].form if reading.words[i].in_compound else samasa_type.stem_of(reading.words[i])
             for i in members]
    recorded = {j.left: j.sutras for j in reading.junctions}
    acc = parts[0]
    for k, nxt in enumerate(parts[1:]):
        outs = sandhi.outcomes(acc, nxt, samasa=True)
        want = recorded.get(members[k])
        plain = next((o for o in outs if o.text == acc + nxt), outs[0] if outs else None)
        pick = next((o for o in outs if want and set(want) <= set(o.sutras)), plain)
        acc = pick.text if pick else acc + nxt
    return acc


def _basis(d: Decision, comp: Compound, chain: str) -> str:
    bracket = f"; bracketing {d.bracket}" + (f" (inner {d.inner})" if d.inner else "") if d.bracket else ""
    return (f"heuristic: {d.samasa} chosen among the types the rules allow ({d.note.split('; classes:')[0]}){bracket}; "
            f"rule chain {chain}")


TADDHITA = "तद्धित"
_SUFFIX_MEMBERS = {"त्व": "त्व", "ता": "तल्"}  # lemma of the member -> the suffix (5.1.119 तस्य भावस्त्वतलौ)


def _suffix_analysis(word: Word) -> int | None:
    """Index of the analysis of ``word`` as the suffix -त्व / -ता that the corpus writes as a member."""
    return next((k for k, a in enumerate(word.analyses) if a.source == "special" and a.lemma in _SUFFIX_MEMBERS), None)


def _taddhita(reading: Reading, cid: int, members: list[int]) -> Compound | None:
    """पात्र-त्वात्, पात्र-ताम्: not a compound but one word, base + -त्व / -ता "the state of being X"."""
    words = reading.words
    if len(members) < 2 or _suffix_analysis(words[members[-1]]) is None:
        return None
    final = words[members[-1]]
    suffix = _SUFFIX_MEMBERS[final.analyses[_suffix_analysis(final)].lemma]
    base = words[members[-2]]
    stem = samasa_type.stem_of(base)
    genitive = samasa_vigraha.form(stem, samasa_vigraha.gender(base, "पुंलिङ्ग"), "षष्ठी", "एकवचन") or stem
    return Compound(id=cid, members=list(members), stem=_surface_stem(reading, members), samasa=TADDHITA,
                    vigraha=f"{genitive} भावः",
                    basis=f"by rule: {stem} + {suffix} by 5.1.119 तस्य भावस्त्वतलौ (the state of being {stem}); one "
                          f"word, which the corpus writes as two members",
                    note="taddhita, not a compound; the suffix member is not derived on its own")


def _build(reading: Reading, cid: int, members: list[int]) -> Compound:
    taddhita = _taddhita(reading, cid, members)
    if taddhita is not None:
        return taddhita
    words = reading.words
    hyphen = "-".join(w.form if w.in_compound else samasa_type.stem_of(w) for w in (words[i] for i in members))
    d = samasa_type.decide(reading, members)
    comp = Compound(id=cid, members=list(members), stem=_surface_stem(reading, members), samasa=d.samasa)
    try:
        chain = derivation(reading, comp, d)
    except Exception as e:  # noqa: BLE001 - derivation unavailable: keep the decision only
        return replace(comp, vigraha=hyphen, basis=_basis(d, comp, f"failed ({e})"), note=f"type: {d.note}")
    codes = ", ".join(dict.fromkeys(t.code for t in chain.trace if t.source == "अष्टाध्यायी"))[:200]
    status = "derivable" if chain.derivable else "not derivable: " + chain.note
    vig = samasa_vigraha.vigraha(reading, members, d) or hyphen
    return replace(comp, vigraha=vig, basis=_basis(d, comp, f"{codes} ({status})"), trace=list(chain.trace),
                   derivable=chain.derivable, note=f"type: {d.note} | chain: {chain.note}")


def annotate(reading: Reading) -> Reading:
    """New Reading with ``compounds`` built, ``Word.compound`` set and member flags checked."""
    words, runs, notes = samasa_group.regroup(list(reading.words))
    words = [replace(w, compound=None) if w.compound is not None else w for w in words]
    for cid, members in enumerate(runs):
        for i in members:
            words[i] = replace(words[i], compound=cid)
    for members in runs:  # the -त्व / -ता member is the suffix, not the pronoun it looks like
        k = _suffix_analysis(words[members[-1]]) if len(members) > 1 else None
        if k is not None:
            words[members[-1]] = replace(words[members[-1]], chosen=k, proof=None)
    base = replace(reading, words=words, notes=list(reading.notes) + notes)
    return replace(base, compounds=[_build(base, cid, members) for cid, members in enumerate(runs)])
